UPDATE travel_shop
SET collect_num = collect_num + #{num}
WHERE id = #{dataId}

UPDATE travel_shop
SET collect_num = collect_num - #{num}
WHERE id = #{dataId}

mapper.select:
SELECT
    s.*,
    st.`name` as shopTypeName
FROM
    travel_shop s
LEFT JOIN travel_shop_type st ON s.type_id = st.id

    
        and s.type_id = #{param.typeId}
    
    
        and st.name like concat('%', #{param.typeName} ,'%')
    
    
        and s.name like concat('%', #{param.name} ,'%')
    
    
        and s.province = #{param.province}
    
    
        and s.city = #{param.city}
    
    
        and s.region = #{param.region}
    
    
        and s.phone = #{param.phone}
    
    
        and s.contactName = #{param.contactName}
    

order by s.create_time desc
